using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class WeatherTool
{
    [McpServerTool, Description("Gets the current weather for a given city.")]
    public static string GetWeather(
        [Description("The city name to get weather for")] string city)
    {
        // Simulated weather data
        return $"The weather in {city} is 72°F and sunny.";
    }
}

using ModelContextProtocol.Server;

namespace McpHttpServer;

public class ConfigurationResourceProvider : McpServerResource
{
    [McpServerResource(Name = "app-config", Description = "Returns the application configuration data.")]
    public static string GetConfiguration()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "Production",
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

